INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'BGN 300m', 'Umsatzschwelle der Phase 1 (oder BGN 3,5m Steuer-/Sozialversicherungszahlungen)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BG' AND s.sort_order = 3;
