INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'B2G-Format & -Plattform', '[["Format", "EN-16931-konforme strukturierte E-Rechnung"], ["Plattform", "Zentralisiertes automatisiertes Informationssystem für die elektronische öffentliche Auftragsvergabe (CAIS EPP)"], ["Rechtsgrundlage", "Artikel 115a, Public Procurement Act (State Gazette 86/18)"], ["Anwendungsbereich", "Verträge oberhalb der EU-Schwellenwerte für die öffentliche Auftragsvergabe, gleichermaßen für zentrale und nachgeordnete Verwaltung"]]', 'Eine Papier- oder einfache PDF-Rechnung erfüllt diese Anforderung nicht — bulgarische Vergabestellen müssen eine wirklich strukturierte E-Rechnung über CAIS EPP empfangen und verarbeiten können.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'file_format' AND dct.title = 'B2G format & platform';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'SAF-T-Meldeformat (getrennt von der Rechnungsstellung)', '[["Format", "XML, ausgerichtet am OECD-SAF-T-Standard"], ["Monatliche Meldung", "Hauptbuch-, Kreditoren-/Debitorendaten sowie Ein- und Verkaufsrechnungsdaten — fällig zum 14. des Folgemonats"], ["Jährliche Meldung", "Anlagevermögensdaten, fällig zusammen mit der Körperschaftsteuererklärung"], ["Auf Anforderung", "Bestandsbewegungsdaten, auf Anfrage der NRA"]]', 'SAF-T ist ein periodischer Buchhaltungsdaten-Export, keine Vorgabe zur Rechnungsausstellung — es ändert nicht, wie Sie eine Rechnung ausstellen, versenden oder empfangen, sondern nur, welche Buchhaltungsdaten Sie periodisch an die NRA melden.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'file_format' AND dct.title = 'SAF-T reporting format (separate from invoicing)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Schrittweise SAF-T-Einführung nach Unternehmensgröße', '[["Phase 1 — 1. Jan. 2026", "Großunternehmen: Umsatz 2023 > BGN 300m, oder Steuer-/Sozialversicherungszahlungen > BGN 3,5m"], ["Phase 2 — 1. Jan. 2027", "Gleiche Schwellenwerte, Daten 2024 — mittlere/kleine Einheiten, die sie überschreiten, kommen hinzu"], ["Phase 3 — 1. Jan. 2028", "Schwellenwert sinkt deutlich: Umsatz 2025 > BGN 15m, oder Zahlungen > BGN 1,5m"], ["Phase 4 — 1. Jan. 2029", "Alle als groß, mittel oder klein eingestuften Unternehmen"], ["Phase 5 — 1. Jan. 2030", "Jede verbleibende mehrwertsteuerlich registrierte Einheit, einschließlich Kleinstunternehmen"]]', 'Jede Phase hat eine dokumentierte sechsmonatige Übergangsfrist, in der Korrekturen an den ersten monatlichen Meldungen ohne Sanktion möglich sind, bis zur Frist des siebten Monats.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'scope_transmission' AND dct.title = 'SAF-T phased rollout by size';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'B2B: vollständig freiwillig', '[["Clearance-Behörde", "Keine"], ["Vorgeschriebener Kanal", "Keiner"], ["Rechtsgrundlage für freiwillige Nutzung", "Bulgarischer VAT Act, abgestimmt auf die EU-Richtlinie 2014/55/EU"]]', 'Ein bulgarisches Unternehmen kann heute strukturierte E-Rechnungen mit einem Handelspartner austauschen, vollständig nach gegenseitiger Vereinbarung — es gibt keine inländische gesetzliche Anforderung, die dies vorantreibt, und keine Sanktion, wenn es unterbleibt.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'scope_transmission' AND dct.title = 'B2B: fully voluntary';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚖️ Es gibt kein Bußgeld für B2B-E-Invoicing — weil es kein B2B-Mandat gibt', NULL, NULL, 'Auf der Rechnungsstellungsseite gibt es nichts zu sanktionieren: Bulgarien hat nie eine B2B-E-Invoicing- oder Clearance-Anforderung gesetzlich verankert, sodass kein Bußgeldkatalog daran anknüpft, wie Sie Rechnungen mit einem anderen Unternehmen ausstellen oder austauschen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'penalties_related' AND dct.title = '⚖️ No B2B e-invoicing fine exists — because no B2B mandate exists';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '📋 SAF-T-Bußgelder sind eine eigenständige steuerverfahrensrechtliche Angelegenheit', NULL, NULL, 'Die Nichteinreichung oder verspätete Einreichung des SAF-T wird von einer einzigen spezialisierten Compliance-Quelle mit einem Bußgeld von BGN 5.000–15.000 für einen Erstverstoß und BGN 10.000–30.000 bei Wiederholung angegeben — behandeln Sie diese Zahlen als plausibel, nicht bestätigt, bis sie mit den eigenen veröffentlichten Leitlinien der NRA abgeglichen wurden.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'penalties_related' AND dct.title = '📋 SAF-T penalties are a separate tax-procedure matter';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie, dass Ihre B2G-Rechnungsstellung bereits über CAIS EPP läuft', 'Wenn Sie bulgarische öffentliche Stellen beliefern, prüfen Sie, ob Ihre Rechnungen als strukturierte EN-16931-E-Rechnungen über CAIS EPP eingereicht werden — diese Pflicht gilt bereits seit November 2019.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BG' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Ermitteln Sie, welche SAF-T-Phase für Sie gilt', 'Vergleichen Sie Ihren Jahresumsatz und Ihre Steuer-/Sozialversicherungszahlungen mit den oben genannten Phasenschwellenwerten, um Ihr erstes verpflichtendes Meldedatum zwischen 2026 und 2030 zu ermitteln.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BG' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Richten Sie SAF-T-fähige Buchhaltungssoftware ein', 'Stellen Sie sicher, dass Ihr Buchhaltungs- oder ERP-System den erforderlichen monatlichen XML-Export von Hauptbuch, Kreditoren-/Debitorendaten und Rechnungsdaten rechtzeitig vor der ersten Frist Ihrer Phase erzeugen kann — die sechsmonatige Übergangsfrist dient Korrekturen, nicht dem Start bei null.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BG' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Verwechseln Sie SAF-T nicht mit einem E-Invoicing-Mandat', 'SAF-T ändert, welche Buchhaltungsdaten Sie wann melden — es verlangt nicht, dass Sie ändern, wie Sie Rechnungen mit anderen Unternehmen ausstellen oder austauschen, da es ein solches Mandat in Bulgarien heute nicht gibt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BG' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Achten Sie auf die Ankündigung eines inländischen B2B-Mandats', 'Bulgarien hat zum Zeitpunkt dieser Rechercherunde keine inländische B2B-E-Invoicing-Ankündigung gemacht, doch die EU-ViDA-Untergrenze zum 1. Juli 2030 gilt unabhängig davon — behalten Sie ein inländisches Mandat im Blick, das wahrscheinlich früher käme.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BG' AND sp.sort_order = 4;

