INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'EU Digital Building Blocks — Bulgarien' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'BG' AND pt.sort_order = 2;

