INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-b2g-2019', 'de',
  'B2G-E-Rechnungsstellung für die öffentliche Auftragsvergabe verpflichtend',
  'Seit dem 1. November 2019 müssen alle öffentlichen Vergabestellen Bulgariens strukturierte, EN-16931-konforme elektronische Rechnungen für Vergabeverfahren oberhalb der EU-Schwellenwerte für die öffentliche Auftragsvergabe empfangen und verarbeiten können, über das zentralisierte automatisierte Informationssystem für die elektronische öffentliche Auftragsvergabe (CAIS EPP). Die Pflicht gilt einheitlich für die zentrale und die nachgeordnete Verwaltung ab einem einzigen Stichtag. Rechtsgrundlage: Artikel 115a des Public Procurement Act (Vergabegesetz; State Gazette 86/18), der die EU-Richtlinie 2014/55/EU umsetzt.',
  '["Historischer Kontext — für bestehende Lieferanten bulgarischer öffentlicher Stellen ist keine Maßnahme erforderlich", "Bestätigen Sie, dass Rechnungen an bulgarische Vergabestellen als strukturierte EN-16931-E-Rechnungen über CAIS EPP eingereicht werden, nicht als PDF oder Papier"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-b2b-voluntary', 'de',
  'B2B-E-Rechnungsstellung bleibt freiwillig — kein CTC- oder Clearance-Mandat',
  'Anders als die Nachbarländer Rumänien oder Polen hat Bulgarien kein Mandat für die elektronische Rechnungsstellung zwischen Unternehmen, kein Echtzeit-Clearance-System und keine fortlaufende Transaktionskontrolle jeglicher Art. Strukturierte E-Rechnungsstellung zwischen Unternehmen ist optional, hängt von einer gegenseitigen Vereinbarung ab und richtet sich nach dem bulgarischen VAT Act (Mehrwertsteuergesetz), abgestimmt auf die EU-Richtlinie 2014/55/EU — Lieferant und Käufer können vereinbaren, EN-16931-E-Rechnungen auszutauschen, doch keine Seite ist dazu verpflichtet.',
  '["Derzeit ist keine inländische B2B-E-Invoicing-Maßnahme erforderlich", "Die kommende SAF-T-Meldepflicht (unten) ist eine periodische Buchhaltungsdatenmeldung, kein Mandat zur Rechnungsausstellung — beides sollte nicht verwechselt werden"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-saft-large-2026', 'de',
  'Periodische SAF-T-Meldung verpflichtend — Großunternehmen (Phase 1)',
  'Ab dem 1. Januar 2026 müssen Bulgariens größte Steuerpflichtige — solche mit einem Nettojahresumsatz 2023 über BGN 300 Millionen oder jährlichen Steuer- und Sozialversicherungszahlungen über BGN 3,5 Millionen — der Nationalen Einnahmenagentur (NAP) monatlich ein Standard Audit File for Tax (SAF-T) übermitteln: Hauptbuch-, Kreditoren-/Debitorendaten sowie Ein- und Verkaufsrechnungsdaten, fällig zum 14. des Folgemonats, zuzüglich eines jährlichen Anlagevermögensberichts. Dies ist eine periodische Buchhaltungsdatenmeldung nach dem geänderten Gesetzbuch über das Steuer- und Sozialversicherungsverfahren (ДОПК) — sie erfordert weder die Ausstellung von E-Rechnungen noch deren Weiterleitung über eine staatliche Plattform.',
  '["Großunternehmen: Stellen Sie sicher, dass SAF-T-fähige Buchhaltungssoftware vor der ersten monatlichen Meldung vorhanden ist", "Dies ist eine Meldepflicht, kein E-Invoicing-Mandat — keine Änderung an der Art, wie Rechnungen ausgestellt oder ausgetauscht werden"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-saft-mediumsmall-2027', 'de',
  'SAF-T Phase 2 — mittlere und kleine Unternehmen treten bei gleichem Schwellenwert bei',
  'Ab dem 1. Januar 2027 kommen Einheiten hinzu, die nach Bulgariens allgemeiner buchhalterischer Größenklassifizierung als mittlere oder kleine Unternehmen gelten und dennoch die Schwellenwerte der Phase 1 überschreiten — BGN 300 Millionen Umsatz 2024 oder BGN 3,5 Millionen Steuer-/Sozialversicherungszahlungen 2024 — und schließen sich den Großunternehmen an, die bereits seit 2026 melden.',
  '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-saft-midtier-2028', 'de',
  'SAF-T Phase 3 — der Schwellenwert sinkt deutlich',
  'Ab dem 1. Januar 2028 sinkt der maßgebliche Schwellenwert auf einen Nettojahresumsatz 2025 über BGN 15 Millionen oder jährliche Steuer- und Sozialversicherungszahlungen über BGN 1,5 Millionen — womit ein deutlich breiteres Segment mittelgroßer bulgarischer Unternehmen erfasst wird.',
  '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-saft-all-2029', 'de',
  'SAF-T Phase 4 — alle großen, mittleren und kleinen Unternehmen',
  'Ab dem 1. Januar 2029 erstreckt sich die SAF-T-Meldung auf alle nach bulgarischem Buchhaltungsrecht als groß, mittel oder klein eingestuften Unternehmen, unabhängig von Umsatz- oder Steuerschwellen — nur Kleinstunternehmen bleiben für ein weiteres Jahr außerhalb des Regimes.',
  '["Stellen Sie SAF-T-fähige Buchhaltungssoftware rechtzeitig vor diesem Datum sicher, falls dies nicht bereits in einer früheren Phase erforderlich war"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-saft-micro-2030', 'de',
  'SAF-T Phase 5 — vollständige Einführung, einschließlich Kleinstunternehmen',
  'Ab dem 1. Januar 2030 erreicht die SAF-T-Meldung jede verbleibende mehrwertsteuerlich registrierte Einheit, einschließlich Kleinstunternehmen, und schließt damit eine fünfjährige, phasenweise Einführung ab, die 2026 mit den größten Steuerpflichtigen begann.',
  '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-vida-2030', 'de',
  'ViDA-grenzüberschreitende B2B-E-Rechnungsstellung und digitale Meldung werden verpflichtend (bestätigtes EU-Recht)',
  'Ab dem 1. Juli 2030 werden gemäß der Richtlinie (EU) 2025/516 des Rates die strukturierte E-Rechnungsstellung und die digitale Meldung für alle innergemeinschaftlichen B2B-Lieferungen verpflichtend — eine feste EU-rechtliche Untergrenze, die für Bulgarien unabhängig davon gilt, ob das Land zuvor ein eigenes inländisches B2B-Mandat einführt. Bulgarien hat zum Zeitpunkt dieser Rechercherunde keine eigenen inländischen B2B-E-Invoicing-Pläne angekündigt; die SAF-T-Meldung (oben) ist eine separate, parallele Pflicht.',
  '["Bereiten Sie sich auf die verpflichtende strukturierte E-Rechnungsstellung für den gesamten innergemeinschaftlichen B2B-Handel ab Mitte 2030 vor", "Beobachten Sie mögliche Ankündigungen eines inländischen bulgarischen B2B-Mandats, das nach dem Muster anderer EU-Mitgliedstaaten wahrscheinlich deutlich vor der EU-Untergrenze 2030 käme"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES (
  '2026-01-01-bulgaria-saft-phase1-launch', 'de',
  'Bulgariens SAF-T-Ära beginnt — aber das ist noch immer kein E-Invoicing-Mandat',
  'Ab dem 1. Januar 2026 müssen Bulgariens größte Steuerpflichtige — solche mit einem Umsatz 2023 über BGN 300 Millionen oder Steuer- und Sozialversicherungszahlungen über BGN 3,5 Millionen — beginnen, monatlich ein Standard Audit File for Tax (SAF-T) bei der Nationalen Einnahmenagentur einzureichen, wobei die erste monatliche Einreichung am 14. Februar 2026 fällig ist. Bulgarien hat weiterhin kein B2B-E-Invoicing-Mandat jeglicher Art.',
  '<h3>🇧🇬 Bulgariens SAF-T-Ära beginnt — aber das ist noch immer kein E-Invoicing-Mandat</h3>
<p>Ab dem 1. Januar 2026 traten Bulgariens größte Steuerpflichtige in die erste Phase einer fünfjährigen, schrittweisen Einführung der Standard-Audit-File-for-Tax-Meldung (SAF-T) ein: Unternehmen mit einem Nettojahresumsatz 2023 über BGN 300 Millionen oder jährlichen Steuer- und Sozialversicherungszahlungen über BGN 3,5 Millionen müssen nun monatlich einen digitalen Export ihres Hauptbuchs, ihrer Kreditoren-/Debitorendaten sowie ihrer Ein- und Verkaufsrechnungsdaten an die Nationale Einnahmenagentur (NAP) übermitteln — mit der ersten monatlichen Meldung fällig am 14. Februar 2026 und einem jährlichen Anlagevermögensbericht, der jeweils im Juni fällig ist.</p>
<p>Es lohnt sich, präzise zu sein, was dies nicht ist: SAF-T ist eine periodische Buchhaltungsdatenmeldepflicht nach dem geänderten Gesetzbuch über das Steuer- und Sozialversicherungsverfahren, kein E-Invoicing-Mandat. Bulgarien verlangt keine strukturierten E-Rechnungen zwischen Unternehmen, hat keine Clearance-Plattform und kein fortlaufendes Transaktions-Reporting für den B2B-Handel — das bleibt vollständig freiwillig. Der SAF-T-Schwellenwert wird bis 2030 in vier weiteren Schritten sinken und schließlich jede mehrwertsteuerlich registrierte Einheit einschließlich Kleinstunternehmen erreichen, doch das zugrunde liegende Rechnungsstellungsregime bleibt davon durchgehend unberührt.</p>'
);



-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr',
  'Pas d''obligation B2B — B2G en vigueur depuis 2019, déclaration SAF-T en déploiement progressif à partir de 2026',
  'Cette page d''analyse reflète le régime de facturation électronique et de déclaration SAF-T de la Bulgarie, tel que confirmé via la fiche pays de facturation électronique de la Commission européenne pour la Bulgarie, ainsi que des sources sectorielles indépendantes (EDICOM, PwC Bulgaria, Penkov Markov & Partners) pour les dates et seuils des phases du SAF-T, à début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Le portail SAF-T de l''Agence nationale des recettes (NRA) bulgare lui-même n''a pas pu être lu de façon automatisée lors de cette série de recherches — confirmez les exigences en vigueur directement auprès de la NRA (nra.bg) ou d''un conseiller fiscal bulgare avant de fonder vos décisions de conformité sur cette page.',
  'La Bulgarie a transposé la directive européenne de facturation électronique B2G le 1er novembre 2019, imposant aux pouvoirs adjudicateurs publics de recevoir des factures électroniques structurées — mais n''a jamais introduit d''obligation interentreprises. Le prochain changement majeur n''est pas du tout une obligation de facturation : à compter du 1er janvier 2026, les plus grands contribuables bulgares doivent commencer à déposer mensuellement un fichier normalisé d''audit fiscal (SAF-T), avec une réduction progressive vers les petites entreprises sur cinq ans, jusqu''en 2030.',
  'La Bulgarie accepte les factures électroniques structurées conformes à la norme EN 16931 pour les marchés publics (B2G) via le système d''information automatisé centralisé pour les marchés publics électroniques (CAIS EPP). Pour le B2B, il n''existe aucun format ni aucune plateforme obligatoires — les partenaires commerciaux sont libres de convenir de la facturation électronique structurée ou de continuer avec le PDF/papier. L''obligation SAF-T distincte, à venir, utilise son propre schéma XML aligné sur la norme OCDE SAF-T, sans lien avec le format de la facture.',
  'La facturation électronique B2G s''applique aux contrats dépassant les seuils de passation des marchés publics de l''UE, de manière uniforme entre pouvoirs adjudicateurs centraux et infra-centraux. La facturation électronique B2B n''a aujourd''hui aucun champ d''application, faute d''obligation. Le champ d''application de la déclaration SAF-T est défini uniquement par la taille : il commence avec les contribuables dépassant 300 millions de BGN de chiffre d''affaires ou 3,5 millions de BGN de paiements d''impôts/cotisations sociales (2026), et s''élargit en quatre étapes supplémentaires jusqu''à atteindre toute entité immatriculée à la TVA, microentreprises comprises, en 2030.',
  'La plupart des entreprises commerçant avec des organismes publics bulgares sont probablement déjà conformes à l''exigence B2G de 2019. La question de conformité actuelle pour 2026 et au-delà est la préparation au SAF-T : les grands contribuables ont dès maintenant besoin d''un logiciel comptable compatible SAF-T, et toute autre entreprise devrait suivre quelle phase de seuil, entre 2027 et 2030, finira par s''appliquer à elle.',
  'La Bulgarie n''a pas de régime de sanctions spécifique à la facturation électronique, faute d''obligation de facturation électronique à faire respecter en B2B. Le non-respect du SAF-T est une infraction distincte et générale de procédure fiscale — les montants de sanctions rapportés (5 000–15 000 BGN pour une première infraction, doublés en cas de récidive) proviennent d''une source unique spécialisée en conformité et sont signalés ici comme plausibles, non confirmés par rapport au texte juridique primaire.',
  'La Bulgarie dispose d''une obligation de facturation électronique B2G (en vigueur depuis le 1er novembre 2019, EN 16931 via CAIS EPP), mais n''a aucune obligation de facturation électronique B2B ni aucune plateforme de clearance ou de contrôle continu des transactions — la facturation électronique B2B reste entièrement facultative. Le prochain événement majeur de conformité est sans lien avec la facturation : une obligation déclarative périodique de données comptables SAF-T en cinq phases, débutant avec les plus grands contribuables le 1er janvier 2026 et atteignant toutes les entités immatriculées à la TVA d''ici 2030. Le plancher ViDA du 1er juillet 2030 constituera la première véritable obligation de facturation électronique B2B transfrontalière de la Bulgarie.',
  '🇧🇬'
FROM countries WHERE code = 'BG';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er nov. 2019', 'Facturation électronique B2G obligatoire pour les marchés publics' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BG' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Aucune obligation', 'La facturation électronique B2B reste entièrement facultative' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BG' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2026', 'Début de la déclaration SAF-T — grandes entreprises en premier (Phase 1)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BG' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'BGN 300m', 'Seuil de chiffre d''affaires de la Phase 1 (ou 3,5 millions de BGN de paiements d''impôts/cotisations sociales)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BG' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '2030', 'Le SAF-T atteint toute entité immatriculée à la TVA (Phase 5)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BG' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et plateforme B2G', '[["Format", "Facture électronique structurée conforme à la norme EN 16931"], ["Plateforme", "Système d''information automatisé centralisé pour les marchés publics électroniques (CAIS EPP)"], ["Base légale", "Article 115a, Public Procurement Act (State Gazette 86/18)"], ["Champ d''application", "Contrats dépassant les seuils de passation des marchés publics de l''UE, aussi bien pour l''administration centrale que infra-centrale"]]', 'Une facture papier ou un simple PDF ne satisfait pas à cette exigence — les pouvoirs adjudicateurs bulgares doivent pouvoir recevoir et traiter une facture électronique véritablement structurée via CAIS EPP.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'file_format' AND dct.title = 'B2G format & platform';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format de déclaration SAF-T (distinct de la facturation)', '[["Format", "XML, aligné sur la norme OCDE SAF-T"], ["Déclaration mensuelle", "Données du grand livre, comptes fournisseurs/clients et données de facturation d''achat et de vente — à échéance le 14 du mois suivant"], ["Déclaration annuelle", "Données sur les immobilisations, à échéance avec la déclaration de l''impôt sur les sociétés"], ["Sur demande", "Données de mouvements de stocks, à la demande de la NRA"]]', 'Le SAF-T est un export périodique de données comptables, non une exigence d''émission de factures — il ne change pas la façon dont vous émettez, envoyez ou recevez une facture, seulement les données comptables que vous déclarez périodiquement à la NRA.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'file_format' AND dct.title = 'SAF-T reporting format (separate from invoicing)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Déploiement échelonné du SAF-T selon la taille', '[["Phase 1 — 1er janv. 2026", "Grandes entreprises : chiffre d''affaires 2023 > 300 millions de BGN, ou paiements d''impôts/cotisations sociales > 3,5 millions de BGN"], ["Phase 2 — 1er janv. 2027", "Mêmes seuils, données 2024 — les entités moyennes/petites qui les dépassent rejoignent le dispositif"], ["Phase 3 — 1er janv. 2028", "Le seuil chute fortement : chiffre d''affaires 2025 > 15 millions de BGN, ou paiements > 1,5 million de BGN"], ["Phase 4 — 1er janv. 2029", "Toutes les entreprises classées grandes, moyennes ou petites"], ["Phase 5 — 1er janv. 2030", "Toute entité restante immatriculée à la TVA, microentreprises comprises"]]', 'Chaque phase comporte une période de grâce documentée de six mois permettant de corriger les premières déclarations mensuelles sans sanction, jusqu''à l''échéance du septième mois.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'scope_transmission' AND dct.title = 'SAF-T phased rollout by size';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'B2B : entièrement facultatif', '[["Autorité de clearance", "Aucune"], ["Canal obligatoire", "Aucun"], ["Base légale de l''usage volontaire", "VAT Act bulgare, aligné sur la directive UE 2014/55/UE"]]', 'Une entreprise bulgare peut aujourd''hui échanger des factures électroniques structurées avec un partenaire commercial, entièrement par accord mutuel — aucune exigence légale nationale ne l''y pousse, et aucune sanction ne s''applique en cas de non-recours à cette pratique.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'scope_transmission' AND dct.title = 'B2B: fully voluntary';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚖️ Aucune sanction de facturation électronique B2B n''existe — car aucune obligation B2B n''existe', NULL, NULL, 'Il n''y a rien à sanctionner sur le plan de la facturation : la Bulgarie n''a jamais légiféré d''exigence de facturation électronique B2B ou de clearance, de sorte qu''aucun barème de sanctions ne se rattache à la façon dont vous émettez ou échangez des factures avec une autre entreprise.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'penalties_related' AND dct.title = '⚖️ No B2B e-invoicing fine exists — because no B2B mandate exists';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '📋 Les sanctions SAF-T relèvent d''une question distincte de procédure fiscale', NULL, NULL, 'Le défaut de dépôt du SAF-T, ou son dépôt tardif, est rapporté par une source unique spécialisée en conformité comme entraînant une amende de 5 000–15 000 BGN pour une première infraction et de 10 000–30 000 BGN en cas de récidive — traitez ces chiffres comme plausibles, non confirmés, tant qu''ils n''ont pas été recoupés avec les propres directives publiées par la NRA.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id JOIN deep_dive_card_translations dct ON dct.card_id = cd.id AND dct.lang = 'en' WHERE c.code = 'BG' AND cd.section = 'penalties_related' AND dct.title = '📋 SAF-T penalties are a separate tax-procedure matter';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Confirmez que votre facturation B2G transite déjà par CAIS EPP', 'Si vous fournissez des organismes publics bulgares, vérifiez que vos factures sont des factures électroniques structurées EN 16931 soumises via CAIS EPP — cette obligation s''applique depuis novembre 2019.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BG' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Déterminez quelle phase du SAF-T vous concerne', 'Comparez votre chiffre d''affaires annuel et vos paiements d''impôts/cotisations sociales aux seuils de phase indiqués ci-dessus pour déterminer votre première date de déclaration obligatoire, entre 2026 et 2030.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BG' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Mettez en place un logiciel comptable compatible SAF-T', 'Assurez-vous que votre système comptable ou ERP peut produire l''export XML mensuel requis du grand livre, des comptes fournisseurs/clients et des données de facturation bien avant la première échéance de votre phase — la période de grâce de six mois sert aux corrections, pas à partir de zéro.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BG' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Ne confondez pas le SAF-T avec une obligation de facturation électronique', 'Le SAF-T modifie les données comptables que vous déclarez et leur fréquence — il ne vous impose pas de changer la façon dont vous émettez ou échangez des factures avec d''autres entreprises, puisqu''aucune obligation de ce type n''existe aujourd''hui en Bulgarie.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BG' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Surveillez une éventuelle annonce d''obligation B2B nationale', 'La Bulgarie n''a fait aucune annonce nationale de facturation électronique B2B à la date de cette série de recherches, mais le plancher de l''UE ViDA du 1er juillet 2030 s''applique néanmoins — surveillez une obligation nationale qui interviendrait probablement plus tôt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BG' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Agence des marchés publics (PPA) — CAIS EPP' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'BG' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Agence nationale des recettes (NRA) — SAF-T' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'BG' AND pt.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'EU Digital Building Blocks — Bulgarie' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'BG' AND pt.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'fr', 'SAF-T non déposé ou déposé tardivement (première infraction) — chiffre plausible, source unique', '5 000–15 000 BGN', '—' FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.code = 'BG' AND dpr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'fr', 'SAF-T non déposé ou déposé tardivement (infraction répétée) — chiffre plausible, source unique', '10 000–30 000 BGN', '—' FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.code = 'BG' AND dpr.sort_order = 1;

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-b2g-2019', 'fr',
  'Facturation électronique B2G obligatoire pour les marchés publics',
  'Depuis le 1er novembre 2019, tous les pouvoirs adjudicateurs du secteur public bulgare doivent être en mesure de recevoir et de traiter des factures électroniques structurées, conformes à la norme EN 16931, pour les marchés publics dépassant les seuils de passation des marchés publics de l''UE, via le système d''information automatisé centralisé pour les marchés publics électroniques (CAIS EPP). L''obligation s''applique de manière uniforme à l''administration centrale et infra-centrale à compter d''une date de conformité unique. Base légale : article 115a du Public Procurement Act (loi sur les marchés publics ; State Gazette 86/18), transposant la directive UE 2014/55/UE.',
  '["Contexte historique — aucune action requise pour les fournisseurs existants d''organismes publics bulgares", "Confirmez que les factures adressées aux pouvoirs adjudicateurs bulgares sont soumises sous forme de factures électroniques structurées EN 16931 via CAIS EPP, et non en PDF ou sur papier"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-b2b-voluntary', 'fr',
  'La facturation électronique B2B reste facultative — aucune obligation de CTC ou de clearance',
  'Contrairement à ses voisines la Roumanie ou la Pologne, la Bulgarie n''a aucune obligation de facturation électronique interentreprises, aucun système de clearance en temps réel, ni aucun contrôle continu des transactions, de quelque nature que ce soit. La facturation électronique structurée entre entreprises est facultative, subordonnée à un accord mutuel, et régie par le VAT Act bulgare (loi sur la TVA), aligné sur la directive UE 2014/55/UE — un fournisseur et un acheteur peuvent convenir d''échanger des factures électroniques EN 16931, mais aucune des deux parties n''y est tenue.',
  '["Aucune action de facturation électronique B2B nationale n''est requise aujourd''hui", "L''obligation de déclaration SAF-T à venir (ci-dessous) est une déclaration périodique de données comptables, et non une obligation d''émission de factures — les deux ne doivent pas être confondues"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-saft-large-2026', 'fr',
  'Déclaration périodique SAF-T obligatoire — grandes entreprises (Phase 1)',
  'À compter du 1er janvier 2026, les plus grands contribuables bulgares — ceux dont le chiffre d''affaires net annuel 2023 dépasse 300 millions de BGN, ou dont les paiements annuels d''impôts et de cotisations sociales dépassent 3,5 millions de BGN — doivent transmettre chaque mois à l''Agence nationale des recettes (NAP) un fichier normalisé d''audit fiscal (SAF-T) : données du grand livre, comptes fournisseurs/clients et données de facturation d''achat/vente, à échéance le 14 du mois suivant, ainsi qu''un rapport annuel sur les immobilisations. Il s''agit d''une déclaration périodique de données comptables au titre du Code de procédure fiscale et de sécurité sociale (ДОПК) modifié — elle n''exige ni l''émission de factures électroniques ni leur transmission via une quelconque plateforme gouvernementale.',
  '["Grands contribuables : assurez-vous de disposer d''un logiciel comptable compatible SAF-T avant la première déclaration mensuelle", "Il s''agit d''une obligation déclarative, non d''une obligation de facturation électronique — aucun changement dans la façon dont les factures sont émises ou échangées"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-saft-mediumsmall-2027', 'fr',
  'SAF-T Phase 2 — les moyennes et petites entreprises rejoignent le dispositif au même seuil',
  'À compter du 1er janvier 2027, les entités classées comme moyennes ou petites entreprises (selon la classification comptable générale bulgare par taille) qui dépassent malgré tout les seuils de la Phase 1 — 300 millions de BGN de chiffre d''affaires 2024, ou 3,5 millions de BGN de paiements d''impôts/cotisations sociales 2024 — rejoignent les grandes entreprises qui déclarent déjà depuis 2026.',
  '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-saft-midtier-2028', 'fr',
  'SAF-T Phase 3 — le seuil chute fortement',
  'À compter du 1er janvier 2028, le seuil applicable descend à un chiffre d''affaires net annuel 2025 supérieur à 15 millions de BGN, ou à des paiements annuels d''impôts et de cotisations sociales supérieurs à 1,5 million de BGN — ce qui fait entrer dans le dispositif une bande beaucoup plus large d''entreprises bulgares de taille moyenne.',
  '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-saft-all-2029', 'fr',
  'SAF-T Phase 4 — toutes les grandes, moyennes et petites entreprises',
  'À compter du 1er janvier 2029, la déclaration SAF-T s''étend à toutes les entreprises classées comme grandes, moyennes ou petites au regard du droit comptable bulgare, indépendamment du chiffre d''affaires ou des seuils fiscaux — ne laissant hors du dispositif, pour une année supplémentaire, que les microentreprises.',
  '["Assurez-vous de disposer d''un logiciel comptable compatible SAF-T bien avant cette date, si cela n''était pas déjà exigé lors d''une phase antérieure"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-saft-micro-2030', 'fr',
  'SAF-T Phase 5 — déploiement complet, microentreprises comprises',
  'À compter du 1er janvier 2030, la déclaration SAF-T atteint toute entité restante immatriculée à la TVA, microentreprises comprises, achevant ainsi un déploiement échelonné sur cinq ans amorcé avec les plus grands contribuables en 2026.',
  '[]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bg-vida-2030', 'fr',
  'La facturation électronique B2B transfrontalière et la déclaration numérique ViDA deviennent obligatoires (droit de l''UE confirmé)',
  'À compter du 1er juillet 2030, en vertu de la directive (UE) 2025/516 du Conseil, la facturation électronique structurée et la déclaration numérique deviennent obligatoires pour toutes les livraisons B2B intracommunautaires — un plancher ferme de droit de l''UE qui s''applique à la Bulgarie, que le pays introduise ou non au préalable sa propre obligation B2B nationale. La Bulgarie n''a annoncé aucun projet national de facturation électronique B2B à la date de cette série de recherches ; la déclaration SAF-T (ci-dessus) est une obligation distincte et parallèle.',
  '["Préparez-vous à la facturation électronique structurée obligatoire pour l''ensemble du commerce B2B intra-UE à partir de mi-2030", "Surveillez toute annonce d''une obligation B2B bulgare nationale, qui interviendrait probablement bien avant le plancher de l''UE de 2030 si elle suit le schéma observé dans d''autres États membres"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES (
  '2026-01-01-bulgaria-saft-phase1-launch', 'fr',
  'L''ère du SAF-T commence en Bulgarie — mais ce n''est toujours pas une obligation de facturation électronique',
  'À compter du 1er janvier 2026, les plus grands contribuables bulgares — ceux dépassant 300 millions de BGN de chiffre d''affaires 2023, ou 3,5 millions de BGN de paiements d''impôts et de cotisations sociales — doivent commencer à déposer mensuellement un fichier normalisé d''audit fiscal (SAF-T) auprès de l''Agence nationale des recettes, la première déclaration mensuelle étant due le 14 février 2026. La Bulgarie n''a toujours aucune obligation de facturation électronique B2B, de quelque nature que ce soit.',
  '<h3>🇧🇬 L''ère du SAF-T commence en Bulgarie — mais ce n''est toujours pas une obligation de facturation électronique</h3>
<p>À compter du 1er janvier 2026, les plus grands contribuables bulgares sont entrés dans la première phase d''un déploiement sur cinq ans de la déclaration du fichier normalisé d''audit fiscal (SAF-T) : les entreprises dont le chiffre d''affaires net annuel 2023 dépasse 300 millions de BGN, ou dont les paiements annuels d''impôts et de cotisations sociales dépassent 3,5 millions de BGN, doivent désormais soumettre chaque mois un export numérique de leur grand livre, de leurs comptes fournisseurs/clients et de leurs données de facturation d''achat/vente à l''Agence nationale des recettes (NAP) — la première déclaration mensuelle étant due le 14 février 2026, et un rapport annuel sur les immobilisations étant dû chaque mois de juin.</p>
<p>Il convient d''être précis sur ce que cela n''est pas : le SAF-T est une obligation déclarative périodique de données comptables au titre du Code de procédure fiscale et de sécurité sociale modifié, et non une obligation de facturation électronique. La Bulgarie n''impose aucune obligation d''émettre des factures électroniques structurées entre entreprises, ne dispose d''aucune plateforme de clearance et d''aucun reporting continu des transactions pour le commerce B2B — cela demeure entièrement facultatif. Le seuil du SAF-T diminuera selon quatre étapes supplémentaires jusqu''en 2030, atteignant finalement toute entité immatriculée à la TVA, microentreprises comprises, mais le régime de facturation sous-jacent reste inchangé tout au long de cette période.</p>'
);
